import 'dart:convert';

import '../models/level.dart';
import '../models/word.dart';

/// Asset generated by `tool/import_lernle.dart`.
const wordsAsset = 'assets/words_de.json';

/// Words per list on the home screen, as in "Words 1 — 50 items".
const wordListSize = 50;

List<Word> parseWords(String json) => [
  for (final row in jsonDecode(json) as List)
    Word.fromJson(row as Map<String, dynamic>),
];

/// A numbered slice of the deck, most frequent words first. All its words
/// share one [level].
class WordList {
  const WordList(this.number, this.words, {this.level = Level.a1});

  /// 1-based position among the lists shown, unique across levels.
  final int number;
  final List<Word> words;
  final Level level;

  String get title => 'Words $number';
}

List<WordList> chunkIntoLists(List<Word> words, {int size = wordListSize}) => [
  for (var i = 0; i < words.length; i += size)
    WordList(
      i ~/ size + 1,
      words.sublist(i, i + size > words.length ? words.length : i + size),
    ),
];

/// Lists of up to [size] words that never mix levels: the words of each
/// level (in the given order) are chunked on their own, numbered on from the
/// previous level.
List<WordList> chunkByLevel(List<Word> words, {int size = wordListSize}) {
  final lists = <WordList>[];
  for (final level in Level.values) {
    final group = [
      for (final w in words)
        if (w.level == level) w,
    ];
    for (var i = 0; i < group.length; i += size) {
      lists.add(
        WordList(
          lists.length + 1,
          group.sublist(i, i + size > group.length ? group.length : i + size),
          level: level,
        ),
      );
    }
  }
  return lists;
}
